-- Run on a disposable database after migrations; all fixture writes roll back.
\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(value boolean, message text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'Assertion failed: %', message; end if; end; $$;
create function pg_temp.expect_error(query text, expected_state text) returns void language plpgsql as $$
begin
  begin execute query;
  exception when others then
    if sqlstate = expected_state then return; end if;
    raise exception 'Expected %, got %: %', expected_state, sqlstate, sqlerrm;
  end;
  raise exception 'Expected rejection: %', query;
end; $$;

